  }

  % n = 10
  \begin{scope}
    \draw[axis] (-0.1, 0) -- (3.65, 0);
    \foreach \k/\h in {0/0.0282, 1/0.1211, 2/0.2335, 3/0.2668, 4/0.2001, 5/0.1029, 6/0.0368, 7/0.0090} {
