    \foreach \k/\h in {0/0.0498, 1/0.1494, 2/0.2240, 3/0.2240, 4/0.1680, 5/0.1008, 6/0.0504, 7/0.0216} {
      \fill[red] ({\k*0.45+0.18}, {\h*\ys}) circle (0.055);
    }
    \foreach \k in {0,...,7} { \node[below, gray] at ({\k*0.45+0.18}, 0) {\k}; }
    \node at (1.7, 2.75) {$n = 200$, $p =$ 0.015};
  \end{scope}

  % Shared x-axis label and legend
  \node[gray] at (6.4, -0.55) {count of successes $k$};
  \draw[bar] (3.1, -1.1) rectangle (3.42, -0.9);
  \node[anchor=west] at (3.5, -1.0) {Binomial($n$, $p$)};
